//! C-interface for the component.
//! This code must be unsafe.
//! Assumptions about correctness are introduced and need to be verified by other means.

use data::*;

#[cfg(test)]
use std::sync::Mutex;

#[cfg(not(test))]
extern "C" {
  fn put_manualActuatorInput1(value: *mut bool) -> bool;
  fn put_manualActuatorInput2(value: *mut bool) -> bool;
}

pub fn unsafe_put_manualActuatorInput1(value: &bool) -> bool
{
  unsafe {
    return put_manualActuatorInput1(value as *const bool as *mut bool);
  }
}

pub fn unsafe_put_manualActuatorInput2(value: &bool) -> bool
{
  unsafe {
    return put_manualActuatorInput2(value as *const bool as *mut bool);
  }
}

//////////////////////////////////////////////////////////////////////////////////
// Testing Versions
//////////////////////////////////////////////////////////////////////////////////

#[cfg(test)]
lazy_static::lazy_static! {
  // simulate the global C variables that point to the microkit shared memory regions.  In a full
  // microkit system we would be able to mutate the shared memory for out ports since they're r/w,
  // but we couldn't do that for in ports since they are read-only
  pub static ref OUT_manualActuatorInput1: Mutex<Option<bool>> = Mutex::new(None);
  pub static ref OUT_manualActuatorInput2: Mutex<Option<bool>> = Mutex::new(None);
}

#[cfg(test)]
pub fn initialize_test_globals() {
  unsafe {
    *OUT_manualActuatorInput1.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_manualActuatorInput2.lock().unwrap_or_else(|e| e.into_inner()) = None;
  }
}

#[cfg(test)]
pub fn put_manualActuatorInput1(value: *mut bool) -> bool
{
  unsafe {
    *OUT_manualActuatorInput1.lock().unwrap_or_else(|e| e.into_inner()) = Some(*value);
    return true;
  }
}

#[cfg(test)]
pub fn put_manualActuatorInput2(value: *mut bool) -> bool
{
  unsafe {
    *OUT_manualActuatorInput2.lock().unwrap_or_else(|e| e.into_inner()) = Some(*value);
    return true;
  }
}
